import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import assert from 'node:assert/strict';
const workspace = process.cwd();
const scratch = mkdtempSync(join(tmpdir(), 'twilight-binary-proof-'));
const prefix = 'openspec/changes/test-axes/evidence/shared-unit-recovery-2026-10-19/';
const paths = ['denial-oracle-receipts.json.gz', 'receipts.json.gz'].map(name => prefix + name);
const cli = join(workspace, 'apps/twilight-structure/twilight-burokrat/cli/src/cli.ts');
function command(argv) {
  return Bun.spawnSync(argv, { cwd: scratch, stdout: 'pipe', stderr: 'pipe' });
}
function git(repository, ...argv) {
  const invocation = command(['git', '-C', repository, ...argv]);
  assert.equal(invocation.exitCode, 0, invocation.stderr.toString());
  return invocation.stdout.toString().trim();
}
function classify(repository, policy) {
  const policyPath = join(scratch, 'classification.json');
  writeFileSync(policyPath, JSON.stringify(policy));
  return command([process.execPath, cli, 'classify-candidate', 'committed', repository, 'HEAD', policyPath]);
}
try {
  for (const name of ['policy.json', 'bootstrap-policy.json']) {
    const policy = JSON.parse(readFileSync(join(workspace, 'docs/wiki-policy', name))).classificationPolicy;
    for (const path of paths) {
      const repository = mkdtempSync(join(scratch, 'candidate-'));
      git(repository, 'init', '--initial-branch=main');
      git(repository, 'config', 'user.email', 'proof@example.test');
      git(repository, 'config', 'user.name', 'Binary Proof');
      mkdirSync(dirname(join(repository, path)), { recursive: true });
      writeFileSync(join(repository, path), readFileSync(join(workspace, path)));
      git(repository, 'add', '--all');
      git(repository, 'commit', '--quiet', '-m', 'exact receipt');
      const accepted = classify(repository, policy);
      assert.equal(accepted.exitCode, 0, accepted.stderr.toString());
      const report = JSON.parse(accepted.stdout.toString());
      assert.equal(report.entries.length, 1);
      assert.equal(report.entries[0].path, path);
      assert.deepEqual(report.entries[0].classification, {
        kind: 'content', contentClass: 'binary', format: 'application/gzip',
        consumer: 'openspec/changes/test-axes/verify.md', regenerationAuthority: {
          kind: 'external', authority: 'Historical execution recorded in openspec/changes/test-axes/verify.md; rerunning its commands produces a new receipt.'
        }
      });
      const removed = classify(repository, { ...policy, binaryDeclarations: policy.binaryDeclarations.filter(declaration => declaration.path !== path) });
      assert.equal(removed.exitCode, 1);
      assert.match(removed.stderr.toString(), new RegExp('undeclared binary content at ' + path.replaceAll('.', '\\.')));
      const control = prefix + 'unlisted-control.json.gz';
      git(repository, 'mv', path, control);
      git(repository, 'commit', '--quiet', '-m', 'unlisted receipt control');
      const refused = classify(repository, policy);
      assert.equal(refused.exitCode, 1);
      assert.ok(refused.stderr.toString().includes('undeclared binary content at ' + control));
      console.log(JSON.stringify({ policy: name, path, declaredExit: accepted.exitCode, omittedExit: removed.exitCode, unlistedExit: refused.exitCode }));
    }
  }
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
